+    for (int i = after.size() - 1; i >= 0; i--) {
+      Node* n = after.at(i);
+      if (!n->is_InlineType()) {
+        after.remove(i);
+      }
+    }
+    uint after_phis = 0;
+    uint after_casts = 0;
+    uint init_nodes = after.size();
+    for (uint i = 0; i < after.size(); ++i) {
+      Node* n = after.at(i);
+      if (n->is_Phi()) {
+        after_phis++;
+        for (uint j = 1; j < n->req(); ++j) {
+          Node *in = n->in(j);
+          if (in != nullptr) {
